import { boot } from 'quasar/wrappers'
import { onAuthStateChanged } from 'firebase/auth'
import { auth } from './firebase'

let initialAuthChecked = false

export default boot(({ router }) => {
  router.beforeEach((to, from, next) => {
    const authRequired = to.matched.some(route => route.meta.authRequired)
    const isAuthenticated = !!auth.currentUser

    if (authRequired) {
      if (isAuthenticated) {
        next()
      } else {
        next({ name: 'sign-in' })
      }
    } else if (isAuthenticated && to.name === 'sign-in') {
      next({ name: 'escala' })
    } else {
      next()
    }
  })

  return new Promise(resolve => {
    const userPermissions = localStorage.getItem('user') ? JSON.parse(localStorage.getItem('user')) : null
    onAuthStateChanged(auth, user => {
      if (user) {
        localStorage.setItem('user', JSON.stringify({ uid: user.uid, email: user.email, ...userPermissions }))
        console.log('Usuário logado:', user.email)
      } else {
        localStorage.removeItem('user')
        console.log('Nenhum usuário logado.')
      }

      if (!initialAuthChecked) {
        initialAuthChecked = true
        resolve()
      }
    })
  })
})
