// src/boot/auth.js
import { defineBoot } from '#q-app/wrappers'
import { createPinia } from 'pinia'
import { supabase } from '../boot/supabase'
import { obterSessaoAtual } from '../api/APIService'
import { useUserStore } from '../stores/user-store'


export default defineBoot(({ app, router }) => {
  /**
   * Guard de rotas - verifica autenticação antes de acessar rotas protegidas
   */
  const pinia = createPinia()
  app.use(pinia)

  router.beforeEach(async (to, from, next) => {
    console.log('Router guard:', to.name, 'authRequired:', to.matched.some(route => route.meta.authRequired))

    const authRequired = to.matched.some(route => route.meta.authRequired)

    const { data: { session } } = await supabase.auth.getSession()
    const isAuthenticated = !!session?.user

    console.log('Session check:', isAuthenticated, session?.user?.email)

    if (authRequired) {
      if (isAuthenticated) {
        console.log('Allowing access to protected route')
        next()
      } else {
        console.log('Redirecting to sign-in')
        next({ name: 'sign-in' })
      }
    } else if (isAuthenticated && (to.name === 'sign-in' || to.name === 'sign-up')) {
      console.log('Redirecting authenticated user from auth pages')
      next({ name: 'escala' })
    } else {
      console.log('Allowing navigation')
      next()
    }
  })

  /**
   * Inicializar autenticação de forma assíncrona
   */
  const userStore = useUserStore()

  // Observar mudanças de autenticação
  supabase.auth.onAuthStateChange(async (event, session) => {
    console.log('Auth state changed:', event, session?.user?.email)

    if (session?.user) {
      try {
        const response = await obterSessaoAtual()
        if (response.error) {
          throw response.error
        }
        const usuarioData = response.data?.usuario
        userStore.setUser({
          uid: session.user.id,
          email: session.user.email,
          usuario: usuarioData || {}
        })
        console.log('✅ Usuário setado no store:', userStore.user)
      } catch (error) {
        console.error('Erro ao buscar dados do usuário:', error)
        userStore.setUser({
          uid: session.user.id,
          email: session.user.email
        })
        console.log('✅ Usuário básico setado no store:', userStore.user)
      }
    } else {
      userStore.clearUser()
      console.log('❌ Usuário removido do store')
    }
  })

  // Retornar Promise resolvida imediatamente
  return Promise.resolve()
})
