def _clean_anon_entity_role_name(name: str) -> str:
    """Remove o prefixo 'NNN - ' do nome do cargo da anon_entity e normaliza espaços.

    Ex: '1231 -  FISCAL DE FRETES' -> 'FISCAL DE FRETES'
        '0001 - AJUDANTE'          -> 'AJUDANTE'
    """
    import re
    if not name:
        return ""
    # Remove prefixo "código - " (com espaços flexíveis ao redor do hífen)
    cleaned = re.sub(r"^\s*\d+\s*-\s*", "", name).strip()
    # Normaliza espaços múltiplos
    cleaned = re.sub(r"\s+", " ", cleaned)
    return cleaned


def build_role_depara(senior_roles: list, anon_entity_roles: list) -> dict:
    """senior.role_name (lower) -> anon_entity.id

    Match em 2 etapas:
    1. Match interno por code (Senior codcar/code <-> anon_entity code) e indexa pelo NOME SENIOR
    2. Fallback por NOME anon_entity (limpo do prefixo "NNN -") indexado direto -
       cobre cargos novos cadastrados na anon_entity que ainda não têm employee Senior alocado.
    """
    anon_entity_by_code = {}
    anon_entity_by_clean_name = {}
    for r in anon_entity_roles:
        code = _s(r.get("code")).lower()
        anon_entity_id = r.get("id")
        if code:
            anon_entity_by_code.setdefault(code, anon_entity_id)
        clean = _clean_anon_entity_role_name(r.get("name") or "").lower()
        if clean:
            anon_entity_by_clean_name.setdefault(clean, anon_entity_id)

    depara = {}
    # 1. Match por code Senior -> anon_entity, indexa pelo nome Senior
    for r in senior_roles:
        s_code = _s(r.get("codcar") or r.get("code")).lower()
        s_name = _s(r.get("name")).lower()
        if s_code and s_name and s_code in anon_entity_by_code:
            depara[s_name] = anon_entity_by_code[s_code]

    # 2. Fallback: adiciona nomes anon_entity limpos diretamente ao de-para
    # (não sobrescreve matches do passo 1)
    for clean_name, anon_entity_id in anon_entity_by_clean_name.items():
        depara.setdefault(clean_name, anon_entity_id)

    return depara


