        return sorted(fl for fl in files if fl.lower().endswith('.csv'))

    def read_file(self, filename: str, retries: int = 3) -> bytes:
        """Lê o conteúdo de um arquivo remoto (bytes), reconectando se o socket cair."""
        last_err = None
        for attempt in range(retries):
            try:
                with self.sftp.open(f'{TRIPS_DIR}{filename}', 'rb') as fh:
                    fh.prefetch()
                    return fh.read()
            except (OSError, EOFError, paramiko.ssh_exception.SSHException) as e:
                last_err = e
                logging.warning('read_file %s falhou (tentativa %d/%d): %s; reconectando',
                                filename, attempt + 1, retries, e)
                self._reconnect()
        raise SFTPUberDashBoardConnectionFailed(
            f'não foi possível ler {filename} após {retries} tentativas: {last_err}')


