/**
 * Extrai até 2 iniciais do nome do responsável para preencher o avatar
 * quando não há foto cadastrada (usuário criado via SSO sem upload).
 */
function iniciaisResponsavel(nome: string | undefined): string {
  if (!nome) return '?';
  const partes = nome.trim().split(/\s+/);
  if (partes.length === 1) return partes[0]?.charAt(0).toUpperCase() ?? '?';
  return (
    (partes[0]?.charAt(0) ?? '') + (partes[partes.length - 1]?.charAt(0) ?? '')
  ).toUpperCase();
}
