async function fetchOccurrencesByPeriod(
  clientSeqValue: string,
  period: OccurrencePeriod
): Promise<Occurrence[]> {
  // Carga padrão usa o seq como act (act=<seq>); as janelas de período
  // (ex.: "UA" = Anteriores) usam act=<periodo> com o seq no corpo.
  const body =
    period === ""
      ? `act=${clientSeqValue}&dummy=${new Date().getTime()}`
      : `act=${period}&seq_cliente=${clientSeqValue}&dummy=${new Date().getTime()}`

  const detailResponse = await fetch(`${SSW_URL()}/bin/ssw0840`, {
    headers: {
      accept: "*/*",
      "accept-language": "pt-PT,pt;q=0.9,en-US;q=0.8,en;q=0.7",
      "content-type": "application/x-www-form-urlencoded; charset=utf-8",
      "sec-ch-ua":
        '"Chromium";v="118", "Google Chrome";v="118", "Not=A?Brand";v="99"',
      "sec-ch-ua-mobile": "?0",
      "sec-ch-ua-platform": '"Windows"',
      "sec-fetch-dest": "empty",
      "sec-fetch-mode": "cors",
      "sec-fetch-site": "same-origin",
      Referer: `${SSW_URL()}/bin/ssw0840`,
      "Referrer-Policy": "strict-origin-when-cross-origin"
    },
    body,
    method: "POST"
  })

  const detailHtml = await detailResponse.text()
  const detailDoc = new DOMParser().parseFromString(detailHtml, "text/html")
  const xmlData = detailDoc.getElementById("xmlsr")
  const rowsData = xmlData?.querySelectorAll("r")

  if (!rowsData) return []

  return Array.from(rowsData).map((row) => ({
    timestamp: row.querySelector("f0")?.textContent,
    user: row.querySelector("f1")?.textContent?.replace(/^#u#|\/u#|#/g, ""),
    description: row.querySelector("f2")?.textContent
  }))
}

async function getClientOccurrences(document?: string): Promise<Occurrence[]> {
  const sswUserData = await getSswUserData()

  const clientSeqInput = getElement.input("seq_cliente")

  let clientSeqValue = ""

  if (clientSeqInput && clientSeqInput.value !== "0") {
    clientSeqValue = clientSeqInput.value
  } else {
    if (!document) return
    clientSeqValue = await getClientSeq(document, sswUserData.username)
  }

  // Busca a carga padrão (recentes) e "Anteriores" (UA) em paralelo. Usamos
  // allSettled para que a falha de uma janela não derrube a outra.
  const periods: OccurrencePeriod[] = ["", "UA"]
  const settled = await Promise.allSettled(
    periods.map((period) => fetchOccurrencesByPeriod(clientSeqValue, period))
  )

  const all = settled
    .filter(
      (result): result is PromiseFulfilledResult<Occurrence[]> =>
        result.status === "fulfilled"
    )
    .flatMap((result) => result.value)

  // Deduplica por timestamp + descrição (as janelas se sobrepõem).
  const seen = new Set<string>()
  const occurrences: Occurrence[] = []

  for (const occurrence of all) {
    const key = `${occurrence.timestamp}|${occurrence.description}`
    if (seen.has(key)) continue
    seen.add(key)
    occurrences.push(occurrence)
  }

  return occurrences
}

