def _semver_tupla(s):
    """(maj, min, patch) a partir de uma string de versão; (0,0,0) se não parsear."""
    nums = re.findall(r'\d+', s or '')
    return tuple(int(n) for n in nums[:3]) + (0,) * (3 - len(nums[:3])) if nums else (0, 0, 0)


def versao_context_processor(request):
    # Versão DEPLOYADA = fonte da verdade do que está no ar (versao.txt; fallback
    # para rpa.__version__ se o arquivo faltar).
    try:
        with open(settings.VERSION_FILE, 'r') as f:
            versao_deploy = f.read().strip()
    except OSError:
        versao_deploy = ''
    if not versao_deploy:
        try:
            from rpa import __version__ as versao_deploy
        except Exception:
            versao_deploy = ''
    if not versao_deploy:
        return {}

    # "Aguardando deploy" só quando existe um anúncio SEMANTICAMENTE maior que o
    # deployado. Compara por SEMVER, não por data_lancamento — os registros de
    # Versao podem ter sido semeados no mesmo instante (ordem por timestamp não
    # confiável), o que fazia o rodapé travar em "Nova Versão Aguardando Deploy!".
    numeros = list(Versao.objects.values_list('numero', flat=True))
    maior = max(numeros, key=_semver_tupla) if numeros else versao_deploy
    aguardando_deploy = _semver_tupla(maior) > _semver_tupla(versao_deploy)

    if aguardando_deploy:
        # Há uma versão anunciada ainda não deployada — mantém o aviso legítimo.
        return {'versao_atual': Versao(numero='Nova Versão Aguardando Deploy!'),
                'nova_versao_disponivel': False}

    # Rodapé mostra a versão realmente deployada (registro real se existir).
    versao_atual = Versao.objects.filter(numero=versao_deploy).order_by('-data_lancamento').first()
    if versao_atual is None:
        versao_atual = Versao(numero=versao_deploy)

    nova_versao_disponivel = False
    if request.user.is_authenticated and hasattr(request.user, 'userprofile'):
        if request.user.userprofile.ultima_versao_vista != versao_deploy:
            nova_versao_disponivel = True

    return {
        'nova_versao_disponivel': nova_versao_disponivel,
        'versao_atual': versao_atual,
    }
