// MapaDadosCriacao devolve register_number → {CPF, e-mail} SÓ das matrículas
// pedidas (filtro `registerNumber in (...)`, em lotes) — fonte do CPF em claro e
// do e-mail (o espelho só guarda cpf_hash). Buscar a base inteira (~11k) estoura
// o deadline do request; por isso filtra pelos elegíveis (dezenas).
func (s *SeniorHTTP) MapaDadosCriacao(ctx context.Context, matriculas []int64) (map[int64]EmployeeCriacao, error) {
	m := make(map[int64]EmployeeCriacao, len(matriculas))
	const lote = 90 // limita tamanho do filtro/URL e mantém 1 página por chamada
	for i := 0; i < len(matriculas); i += lote {
		fim := i + lote
		if fim > len(matriculas) {
			fim = len(matriculas)
		}
		ids := make([]string, 0, fim-i)
		for _, mm := range matriculas[i:fim] {
			ids = append(ids, strconv.FormatInt(mm, 10))
		}
		q := url.Values{}
		q.Set("displayfields", "*,person.*")
		q.Set("filter", "registerNumber in ("+strings.Join(ids, ",")+")")
		raws, err := s.listarPaginado(ctx, "/hcm/employeejourney/entities/employee", q)
		if err != nil {
			return nil, err
		}
		s.acumulaDadosCriacao(m, raws)
	}
	return m, nil
}

