func (r *Registrador) ListarAtividades(ctx context.Context, f FiltroAtividades) ([]AtividadeRow, error) {
	if f.Limit <= 0 || f.Limit > 500 {
		f.Limit = 100
	}
	conds := []string{"1=1"}
	args := []any{}
	add := func(cond string, val any) {
		args = append(args, val)
		conds = append(conds, fmt.Sprintf(cond, len(args)))
	}
	if f.Colaborador != "" {
