		// "Usuário" agora casa por e-mail OU nome do colaborador (busca fácil).
		// Um único valor, dois placeholders → mesmo índice nas duas posições.
		args = append(args, f.Email)
		i := len(args)
		conds = append(conds, fmt.Sprintf(
			"(a.email ILIKE '%%' || $%d || '%%' OR c.nome_completo ILIKE '%%' || $%d || '%%')", i, i))
	}
	if f.Tipo != "" {
		add("a.tipo = $%d", f.Tipo)
	}
	if f.Modulo != "" {
		add("a.modulo = $%d", f.Modulo)
	}
	if f.De != nil {
		add("a.ts >= $%d", *f.De)
	}
	if f.Ate != nil {
		add("a.ts <= $%d", *f.Ate)
	}
	args = append(args, f.Limit)
	limIdx := len(args)
	args = append(args, f.Offset)
	offIdx := len(args)

	// Nome via LEFT JOIN em colaborador.colaboradores (nome_completo é texto puro
	// — não PII cifrada). Sem colaborador casado, nome vem vazio (mostra e-mail).
	q := fmt.Sprintf(`SELECT a.id, a.ts, COALESCE(a.email,''), COALESCE(c.nome_completo,''),
		a.tipo, COALESCE(a.modulo,''),
		COALESCE(a.rota,''), COALESCE(a.elemento,''), COALESCE(a.metodo,''),
		COALESCE(a.status,0), COALESCE(host(a.ip),''), a.detalhes
		FROM auditoria.atividades a
		LEFT JOIN colaborador.colaboradores c ON c.id = a.colaborador_id
		WHERE %s
		ORDER BY a.ts DESC, a.id DESC LIMIT $%d OFFSET $%d`,
		strings.Join(conds, " AND "), limIdx, offIdx)

	rows, err := r.pool.Query(ctx, q, args...)
	if err != nil {
		return nil, fmt.Errorf("listar atividades: %w", err)
	}
	defer rows.Close()
	var out []AtividadeRow
