async function cookieHeader(): Promise<string> {
  const store = await cookies();
  return store
    .getAll()
    .map((c) => `${c.name}=${c.value}`)
    .join('; ');
}

type AcaoResult =
  | { ok: true; aviso?: string }
  | { ok: false; codigo: string; mensagem: string };

async function chamar(url: string, metodo: 'POST' | 'DELETE'): Promise<AcaoResult> {
  const res = await fetch(url, {
    method: metodo,
    headers: { cookie: await cookieHeader() },
    cache: 'no-store',
  });
  if (res.status === 204) {
    revalidatePath('/admin/usuarios');
    return { ok: true };
  }
  // 200 com corpo: a exclusão definitiva conta o que mexeu além do cadastro
  // (autoria de notícia/documento reapontada para quem executou). Isso não pode
  // passar em silêncio, então volta como aviso para a tela mostrar.
  if (res.status === 200) {
    revalidatePath('/admin/usuarios');
    const corpo = (await res.json().catch(() => null)) as
      | { autoria_transferida?: number; atuacao_limpa?: number }
      | null;
    const autoria = corpo?.autoria_transferida ?? 0;
    return {
      ok: true,
      ...(autoria > 0
        ? {
            aviso:
              `${autoria} conteúdo(s) que essa conta havia publicado agora estão ` +
              'no seu nome — apagar o cadastro não apaga comunicado.',
          }
        : {}),
    };
  }
  const body = (await res.json().catch(() => null)) as
    | { error?: { code?: string; message?: string } }
    | null;
  return {
    ok: false,
    codigo: body?.error?.code ?? 'ERRO',
    mensagem: body?.error?.message ?? `HTTP ${res.status}`,
  };
}

export async function inativar(colaboradorId: string): Promise<AcaoResult> {
  return chamar(`${apiInternal}/api/v1/colaboradores/${colaboradorId}/inativar`, 'POST');
