// Após o pre-cadastro ser criado, a sessão de cadastro é revogada e
// substituída por uma sessão normal de status `pre_cadastro`.
type SessaoTipo string

const (
	SessaoTipoNormal   SessaoTipo = "normal"
	SessaoTipoCadastro SessaoTipo = "cadastro"
)

// Sessao representa uma sessão autenticada de colaborador.
// Persistida no Redis (não JWT no cookie) — permite revogação imediata.
type Sessao struct {
	ID            string // valor opaco do cookie, 256 bits b64
	Tipo          SessaoTipo
	ColaboradorID uuid.UUID // uuid.Nil quando Tipo = cadastro
	Email         string
	Nome          string
	FotoURL       string
	Perfil        string
	StatusColab   string
	// AdminLiberado: um administrador liberou EXPLICITAMENTE o acesso às telas
	// de Administração desta pessoa (coluna `admin_liberado_em`). Ter o perfil
	// não basta — ver AdminEfetivo.
	AdminLiberado   bool
	MFAOk           bool
	IP              string
	UserAgent       string
	CriadaEm        time.Time
	ExpiraAbsoluto  time.Time
	UltimaAtividade time.Time

	// PreFill é populado apenas em sessões `cadastro` — dados do Workspace
	// para pré-preencher o formulário de cadastro. Vazio em sessões normais.
	PreFill PerfilWorkspace
}

// AdminEfetivo é a ÚNICA forma legítima de perguntar "esta sessão tem poder de
// administrador?".
//
// Perfil `administrador` sozinho não responde: o pré-cadastro auto-aprova pelo
// CPF, que é auto-declarado, então o perfil pode ter vindo do CPF de outra
// pessoa. O poder administrativo só vale depois que um administrador já liberado
// aprovou (RN-PROV-008, migration 0079).
//
// Comparar `sess.Perfil == "administrador"` direto é proibido — há um teste que
// varre o código e falha se aparecer (perfil_administrador_test.go). O motivo é
// concreto: eram 33 pontos de short-circuit no backend, e um único esquecido
// devolve o privilégio inteiro.
func (s Sessao) AdminEfetivo() bool {
	return s.Perfil == PerfilAdministrador && s.AdminLiberado
}

// PerfilAdministrador — o slug do perfil de maior privilégio. Existe aqui para
// o resto do código não repetir a string solta.
const PerfilAdministrador = "administrador"

// Expirada aplica RN-AUTH-005: sessão idle > 15min OU absoluta > 8h.
func (s *Sessao) Expirada(agora time.Time, idleMax time.Duration) bool {
	if agora.After(s.ExpiraAbsoluto) {
		return true
	}
	if agora.Sub(s.UltimaAtividade) > idleMax {
		return true
	}
	return false
}

