/**
 * Cliente HTTP simples para o backend anon_entity.
 *
 * `VITE_API_BASE` é injetado no build pelo .gitlab-ci.yml; em dev
 * fallback para localhost. A API key vem do localStorage (página Settings).
 */

export const API_BASE = import.meta.env.VITE_API_BASE ?? "http://anon.invalid";

/**
 * Cliente HTTP que envia/recebe cookies de sessão.
 *
 * Toda chamada usa `credentials: 'include'`, então o cookie HttpOnly
 * `wcb_session` (setado pelo backend após /auth/login) vai automaticamente.
 * JS nunca toca na API key.
 */
async function request<T>(path: string, init: RequestInit = {}): Promise<T> {
  const res = await fetch(`${API_BASE}${path}`, {
    ...init,
    credentials: "include",
    headers: {
      "Content-Type": "application/json",
      ...init.headers,
    },
  });
  if (!res.ok) {
    const text = await res.text();
    const err = new Error(`${res.status} ${res.statusText}: ${text}`) as Error & { status?: number };
    err.status = res.status;
    throw err;
  }
  return res.status === 204 ? (undefined as T) : ((await res.json()) as T);
}

